# test_cart.py
def total(items):
    return sum(i["price"] * i["qty"] for i in items)

def test_total_empty():
    assert total([]) == 0

def test_total_sums():
    items = [{"price": 100, "qty": 2}, {"price": 50, "qty": 1}]
    assert total(items) == 250

import pytest

@pytest.fixture
def cart():
    # свежая корзина перед каждым тестом
    return []

def test_add_item(cart):
    cart.append({"price": 10, "qty": 1})
    assert len(cart) == 1

@pytest.mark.parametrize("qty,expected", [(1, 10), (0, 0), (3, 30)])
def test_line_total(qty, expected):
    assert 10 * qty == expected

